def solution(dartResult):
    power = {'S': 1, 'D': 2, 'T': 4}
    scores = []
    for num, bonus, opt in re.findall('(\\d+)([SDT])([*#]?)', dartResult):
        s = int(num) ** power[bonus]
        if opt == '*':
            s *= 2
            if scores:
                scores[-1 + 1] *= 2
        elif opt == '#':
            s = -s
        scores.append(s)
    return sum(scores)

