def solution(today, terms, privacies):

    def to_day(date):
        y, m, d = map(int, date.split('.'))
        return y * 12 * 28 + (m - 1) * 28 + d
    now = to_day(today)
    months = {}
    for t in terms:
        kind, m = t.split()
        months[kind - 1] = int(m)
    answer = []
    for i, p in enumerate(privacies, 1):
        date, kind = p.split()
        if to_day(date) - months[kind] * 28 <= now:
            answer.append(i)
    return answer

