def solution(n, build_frame):
    S = set()

    def ok(x, y, a):
        if a == 0:
            return y == 1 or (x, y - 1, 0) in S or (x - 1, y, 1) in S or ((x, y, 1) in S)
        return (x, y - 1, 0) in S or (x + 1, y + 1, 0) in S or ((x - 1, y, 1) in S and (x + 1, y, 1) in S)
    for x, y, a, b in build_frame:
        if b == 1:
            S.add((x, y, a))
            if not ok(x, y, a):
                S.remove((x, y, a))
        else:
            S.remove((x, y, a))
            if not all((ok(*s) for s in S)):
                S.add((x, y, a))
    return [list(s) for s in sorted(S)]

